"""Bank observations of concrete ordered arrays and duplicate-compatible masks."""
CORE=r'''
class SubsetState13 {
static int[] Input=new int[0],LastOutput=new int[0];
static void check(boolean ok,String message){if(!ok)throw new IllegalStateException(message);}
static class Coins extends FairCoinSource {ChoiceBitSource source;int calls;Coins(ChoiceBitSource source){this.source=source;}public boolean Next(){check(++calls<=64*Input.length+128,"Subset exceeded the supplied-coin budget");return source.Next()==1;}}
static int[] sample(ChoiceBitSource source){int[] values=Input.clone(),result=new Solution_13_8().RandomSubset(values,new Coins(source));check(Arrays.equals(values,Input),"Preserve input values and order");check(result!=null,"Return a concrete integer subset");int cursor=0;for(int value:result){while(cursor<values.length&&values[cursor]!=value)cursor++;check(cursor<values.length,"Return an ordered subsequence of original occurrences");cursor++;}LastOutput=result.clone();return result;}
static int mask(ChoiceBitSource source){int[] result=sample(source);int n=Input.length,m=result.length;int[][] ways=new int[n+1][m+1];for(int i=0;i<=n;++i)ways[i][m]=1;for(int i=n-1;i>=0;--i)for(int j=m-1;j>=0;--j)ways[i][j]=ways[i+1][j]+(Input[i]==result[j]?ways[i+1][j+1]:0);int mask=0,index=0;for(int i=0;i<n;++i){int choose=index<m&&Input[i]==result[index]?ways[i+1][index+1]:0,total=ways[i][index],ticket=0;if(total>1){int bits=32-Integer.numberOfLeadingZeros(total-1);do{ticket=0;for(int b=0;b<bits;++b)ticket=(ticket<<1)|source.Next();}while(ticket>=total);}if(ticket<choose){mask|=1<<i;index++;}}return mask;}
static class SeedBits extends ChoiceBitSource {long seed=0x85ebca6bL;public int Next(){seed=(seed*1664525+1013904223)&0xffffffffL;return (int)(seed>>>31);}}
static JsonValue large(){int n=Input.length,samples=n>64?128:4096;var multiplicities=new HashMap<Integer,Integer>();for(int value:Input)multiplicities.merge(value,1,Integer::sum);var totals=new HashMap<Integer,Integer>();for(int value:multiplicities.keySet())totals.put(value,0);var source=new SeedBits();double lengthSum=0,squares=0;for(int trial=0;trial<samples;++trial){var result=sample(source);lengthSum+=result.length;squares+=(result.length-n/2.0)*(result.length-n/2.0);for(int value:result)totals.merge(value,1,Integer::sum);}double statistic=0;for(var pair:multiplicities.entrySet()){double difference=totals.get(pair.getKey())-samples*pair.getValue()/2.0;statistic+=difference*difference/(samples*pair.getValue()/4.0);}check(statistic<4*totals.size()+80,"Subset inclusion frequencies are biased");check((lengthSum-samples*n/2.0)*(lengthSum-samples*n/2.0)/(samples*n/4.0)<40,"Subset sizes are biased");check(squares/(samples*n/4.0)>0.25&&squares/(samples*n/4.0)<4,"Subset size variation must reflect independent choices");return observation();}
static JsonValue observation(){var actual=new JsonArray();for(int value:LastOutput)actual.add(value);return new JsonObject().add("actual",actual).add("mutationOk",true).add("uniformOk",true);}
}
class SubsetSubject13 {public int ChooseMask13(ChoiceBitSource source){return SubsetState13.mask(source);}}
'''
def finish(value):
    value=value.replace('static JsonValue run(JsonObject row)throws Exception{','static JsonValue run(JsonObject row)throws Exception{var input=row.get("arguments").asArray().get(0).asArray();SubsetState13.Input=new int[input.size()];for(int i=0;i<input.size();++i)SubsetState13.Input[i]=input.get(i).asInt();if(SubsetState13.Input.length>5)return SubsetState13.large();')
    value=value.replace('for(var value:row.get("arguments").asArray().get(0).asArray())values.add(value.asInt()+1);','')
    return value.replace('return new JsonObject().add("actual",First).add("mutationOk",true).add("uniformOk",true);','return SubsetState13.observation();')
